import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';

function safelyRemoveLayer(map: maplibregl.Map, layerId: string) {
  try {
    if (map.getLayer(layerId)) {
      map.removeLayer(layerId);
    }
  } catch {
    // Map style may already be disposed during route transitions/unmount.
  }
}

function safelyRemoveSource(map: maplibregl.Map, sourceId: string) {
  try {
    if (map.getSource(sourceId)) {
      map.removeSource(sourceId);
    }
  } catch {
    // Map style may already be disposed during route transitions/unmount.
  }
}

interface UseGeoJsonLayersArgs {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  data?: GeoJSON.GeoJSON | string | null;
  id: string;
  type: 'fill' | 'line' | 'circle';
  visible: boolean;
  minZoom?: number;
  maxZoom?: number;
  filter?: unknown[];
  sourceId: string;
  labelSourceId: string;
  layerIdFill: string;
  layerIdLine: string;
  layerIdCircle: string;
  layerIdLabel: string;
  fillColor: unknown;
  fillOpacity: unknown;
  fillPattern?: unknown;
  lineColor: unknown;
  lineWidth: unknown;
  lineOpacity: unknown;
  lineDashArray?: number[];
  lineCap?: 'butt' | 'round' | 'square';
  lineJoin?: 'bevel' | 'round' | 'miter';
  circleRadius: unknown;
  circleColor: unknown;
  circleOpacity: unknown;
  circleStrokeColor: unknown;
  circleStrokeWidth: unknown;
}

export function useGeoJsonLayers({
  map,
  isLoaded,
  data,
  id,
  type,
  visible,
  minZoom,
  maxZoom,
  filter,
  sourceId,
  labelSourceId,
  layerIdFill,
  layerIdLine,
  layerIdCircle,
  layerIdLabel,
  fillColor,
  fillOpacity,
  fillPattern,
  lineColor,
  lineWidth,
  lineOpacity,
  lineDashArray,
  lineCap,
  lineJoin,
  circleRadius,
  circleColor,
  circleOpacity,
  circleStrokeColor,
  circleStrokeWidth,
}: UseGeoJsonLayersArgs) {
  useEffect(() => {
    console.log(`[GeoJsonLayer ${id}] useEffect triggered:`, {
      hasMap: !!map,
      isLoaded,
      hasData: !!data,
      dataType: data && typeof data === 'object' ? (data as GeoJSON.GeoJSON).type : null,
      featureCount:
        data && typeof data === 'object' && 'features' in data
          ? (data as GeoJSON.FeatureCollection).features?.length
          : 'N/A',
    });

    if (!map || !isLoaded || !data) {
      console.log(`[GeoJsonLayer ${id}] Early return:`, { map: !!map, isLoaded, data: !!data });
      return;
    }

    if (!map.getSource(sourceId)) {
      return;
    }

    console.log(`[GeoJsonLayer ${id}] Map is ready, adding layers...`);

    const layerOptions = {
      minzoom: minZoom,
      maxzoom: maxZoom,
      filter: filter as maplibregl.FilterSpecification | undefined,
    };

    console.log(`[GeoJsonLayer ${id}] Layer type: ${type}, adding layers...`);

    if (type === 'fill' || type === 'line') {
      if (!map.getLayer(layerIdFill)) {
        console.log(
          `[GeoJsonLayer ${id}] Creating fill layer: ${layerIdFill} with fillColor=${fillColor}, fillOpacity=${fillOpacity}`
        );
        try {
          map.addLayer({
            id: layerIdFill,
            type: 'fill',
            source: sourceId,
            ...layerOptions,
            layout: {
              visibility: visible ? 'visible' : 'none',
            },
            paint: {
              'fill-color': fillColor as string,
              'fill-opacity': [
                'case',
                ['boolean', ['feature-state', 'hover'], false],
                Math.min((fillOpacity as number) + 0.2, 1),
                fillOpacity as number,
              ],
              ...(fillPattern !== undefined && {
                'fill-pattern': fillPattern as string | maplibregl.ExpressionSpecification,
              }),
            },
            filter: [
              'any',
              ['==', ['geometry-type'], 'Polygon'],
              ['==', ['geometry-type'], 'MultiPolygon'],
            ],
          });
          console.log(`[GeoJsonLayer ${id}] Fill layer created successfully`);
        } catch (err) {
          console.error(`[GeoJsonLayer ${id}] Error creating fill layer:`, err);
        }
      } else {
        console.log(`[GeoJsonLayer ${id}] Fill layer already exists`);
      }

      if (!map.getLayer(layerIdLine)) {
        console.log(
          `[GeoJsonLayer ${id}] Creating line layer: ${layerIdLine} with lineColor=${lineColor}, lineWidth=${lineWidth}`
        );
        try {
          map.addLayer({
            id: layerIdLine,
            type: 'line',
            source: sourceId,
            ...layerOptions,
            layout: {
              visibility: visible ? 'visible' : 'none',
              ...(lineCap && { 'line-cap': lineCap }),
              ...(lineJoin && { 'line-join': lineJoin }),
            },
            paint: {
              'line-color': lineColor as string,
              'line-width': [
                'case',
                ['boolean', ['feature-state', 'hover'], false],
                (lineWidth as number) + 1,
                lineWidth as number,
              ],
              'line-opacity': lineOpacity as number,
              ...(lineDashArray && { 'line-dasharray': lineDashArray }),
            },
            filter: [
              'any',
              ['==', ['geometry-type'], 'Polygon'],
              ['==', ['geometry-type'], 'MultiPolygon'],
              ['==', ['geometry-type'], 'LineString'],
              ['==', ['geometry-type'], 'MultiLineString'],
            ],
          });
          console.log(`[GeoJsonLayer ${id}] Line layer created successfully`);
        } catch (err) {
          console.error(`[GeoJsonLayer ${id}] Error creating line layer:`, err);
        }
      } else {
        console.log(`[GeoJsonLayer ${id}] Line layer already exists`);
      }

      console.log(
        `[GeoJsonLayer ${id}] Layers created. Checking: fill=${!!map.getLayer(layerIdFill)}, line=${!!map.getLayer(
          layerIdLine
        )}`
      );
    }

    if (type === 'circle') {
      if (!map.getLayer(layerIdCircle)) {
        map.addLayer({
          id: layerIdCircle,
          type: 'circle',
          source: sourceId,
          ...layerOptions,
          layout: {
            visibility: visible ? 'visible' : 'none',
          },
          paint: {
            'circle-radius': circleRadius as number,
            'circle-color': circleColor as string,
            'circle-opacity': circleOpacity as number,
            'circle-stroke-color': circleStrokeColor as string,
            'circle-stroke-width': circleStrokeWidth as number,
          },
          filter: ['any', ['==', ['geometry-type'], 'Point'], ['==', ['geometry-type'], 'MultiPoint']],
        });
      }
    }

    return () => {
      safelyRemoveLayer(map, layerIdLabel);
      safelyRemoveLayer(map, layerIdFill);
      safelyRemoveLayer(map, layerIdLine);
      safelyRemoveLayer(map, layerIdCircle);
      safelyRemoveSource(map, labelSourceId);
      safelyRemoveSource(map, sourceId);
    };
  }, [map, isLoaded, id, data]); // eslint-disable-line react-hooks/exhaustive-deps
}
