/**
 * Built-in map style URLs
 * 
 * These are free, publicly available map styles that don't require API keys.
 */

import type { StyleSpecification } from 'maplibre-gl';
import type { MapStylePreset, MapStyle } from '../types';

/**
 * Map style URLs by preset name.
 */
export const MAP_STYLE_URLS: Record<MapStylePreset, string> = {
  /**
   * Liberty — Clean, modern style based on OSM.
   * Provider: OpenFreeMap (free, no limits, ODbL license)
   * https://openfreemap.org
   */
  'liberty': 'https://tiles.openfreemap.org/styles/liberty',
  
  /**
   * Bright — Colorful OSM-based style.
   * Provider: OpenFreeMap (free, no limits, ODbL license)
   */
  'bright': 'https://tiles.openfreemap.org/styles/bright',
  
  /**
   * Positron — Light, minimal style with subtle colors.
   * Good for data visualization overlays.
   * Provider: OpenFreeMap (free, no limits, ODbL license)
   */
  'positron': 'https://tiles.openfreemap.org/styles/positron',
  
  /**
   * Dark Matter — Dark style with bright labels.
   * Good for night mode and contrast with bright data.
   * Provider: OpenFreeMap (free, no limits, ODbL license)
   */
  'dark-matter': 'https://tiles.openfreemap.org/styles/dark',
  
  /**
   * Nature — Style with custom nature colors (green land, blue water).
   * Based on Positron, colors applied dynamically in editor.
   */
  'nature': 'https://tiles.openfreemap.org/styles/positron',
  
  /**
   * Custom — User-defined colors.
   * Based on Positron, colors applied dynamically in editor.
   */
  'custom': 'https://tiles.openfreemap.org/styles/positron',
};

/**
 * Default map style preset.
 */
export const DEFAULT_STYLE_PRESET: MapStylePreset = 'positron';

/**
 * Resolve a MapStyle to a URL string or StyleSpecification.
 * 
 * @param style - Style preset name, URL, or StyleSpecification
 * @returns URL string or the original StyleSpecification
 */
export function resolveMapStyle(style: MapStyle): string | StyleSpecification {
  if (typeof style === 'string' && style in MAP_STYLE_URLS) {
    return MAP_STYLE_URLS[style as MapStylePreset];
  }
  return style as string | StyleSpecification;
}

