import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';
import type { MapLayerMouseEvent, MapGeoJSONFeature } from 'maplibre-gl';

import type { FeatureEvent, GeoCoordinates, GeoJsonLayerProps } from '../../types';

type CreateFeatureEvent<P> = (
  feature: MapGeoJSONFeature,
  coordinates: GeoCoordinates,
  originalEvent: MouseEvent
) => FeatureEvent<P>;

interface UseFeatureHoverArgs<P> {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  hoverable: boolean;
  type: GeoJsonLayerProps['type'];
  sourceId: string;
  layerIdFill: string;
  layerIdCircle: string;
  hoveredFeatureId: React.MutableRefObject<string | number | null>;
  onFeatureHover?: (event: FeatureEvent<P> | null) => void;
  createFeatureEvent: CreateFeatureEvent<P>;
}

export function useFeatureHover<P>({
  map,
  isLoaded,
  hoverable,
  type,
  sourceId,
  layerIdFill,
  layerIdCircle,
  hoveredFeatureId,
  onFeatureHover,
  createFeatureEvent,
}: UseFeatureHoverArgs<P>) {
  useEffect(() => {
    if (!map || !isLoaded || !hoverable) return;

    const targetLayer = type === 'circle' ? layerIdCircle : layerIdFill;
    if (!map.getLayer(targetLayer)) return;

    const handleMouseMove = (e: MapLayerMouseEvent) => {
      if (!e.features || e.features.length === 0) return;

      const feature = e.features[0];

      if (hoveredFeatureId.current !== null && hoveredFeatureId.current !== feature.id) {
        map.setFeatureState(
          { source: sourceId, id: hoveredFeatureId.current },
          { hover: false }
        );
      }

      if (feature.id !== undefined) {
        hoveredFeatureId.current = feature.id;
        map.setFeatureState(
          { source: sourceId, id: feature.id },
          { hover: true }
        );
      }

      map.getCanvas().style.cursor = 'pointer';

      if (onFeatureHover) {
        const coords: GeoCoordinates = [e.lngLat.lng, e.lngLat.lat];
        onFeatureHover(createFeatureEvent(feature, coords, e.originalEvent));
      }
    };

    const handleMouseLeave = () => {
      if (hoveredFeatureId.current !== null) {
        map.setFeatureState(
          { source: sourceId, id: hoveredFeatureId.current },
          { hover: false }
        );
        hoveredFeatureId.current = null;
      }

      map.getCanvas().style.cursor = '';
      onFeatureHover?.(null);
    };

    map.on('mousemove', targetLayer, handleMouseMove);
    map.on('mouseleave', targetLayer, handleMouseLeave);

    return () => {
      map.off('mousemove', targetLayer, handleMouseMove);
      map.off('mouseleave', targetLayer, handleMouseLeave);
    };
  }, [
    map,
    isLoaded,
    hoverable,
    type,
    sourceId,
    onFeatureHover,
    layerIdFill,
    layerIdCircle,
    hoveredFeatureId,
    createFeatureEvent,
  ]);
}
