import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';
import type { GeoJSONSource } from 'maplibre-gl';

import type { GeoJsonLayerProps } from '../../types';
import { createCentroidsGeoJson } from './labelUtils';

interface UseLabelLayerArgs {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  data: GeoJSON.GeoJSON | null | undefined;
  labelField?: GeoJsonLayerProps['labelField'];
  labelFormatNumbers: boolean;
  labelFilter?: GeoJsonLayerProps['labelFilter'];
  labelOpacity?: GeoJsonLayerProps['labelOpacity'];
  labelSize: number;
  labelColor: string;
  labelHaloColor: string;
  labelHaloWidth: number;
  labelFont: string[];
  labelAnchor: GeoJsonLayerProps['labelAnchor'];
  labelOffset?: GeoJsonLayerProps['labelOffset'];
  labelMinZoom?: number;
  labelMaxZoom?: number;
  labelAllowOverlap: boolean;
  minZoom?: number;
  maxZoom?: number;
  labelSourceId: string;
  layerIdLabel: string;
}

export function useLabelLayer({
  map,
  isLoaded,
  data,
  labelField,
  labelFormatNumbers,
  labelFilter,
  labelOpacity,
  labelSize,
  labelColor,
  labelHaloColor,
  labelHaloWidth,
  labelFont,
  labelAnchor,
  labelOffset,
  labelMinZoom,
  labelMaxZoom,
  labelAllowOverlap,
  minZoom,
  maxZoom,
  labelSourceId,
  layerIdLabel,
}: UseLabelLayerArgs) {
  useEffect(() => {
    if (!map || !isLoaded || !data) return;

    if (!labelField) {
      if (map.getLayer(layerIdLabel)) {
        map.removeLayer(layerIdLabel);
      }
      if (map.getSource(labelSourceId)) {
        map.removeSource(labelSourceId);
      }
      return;
    }

    const labelFieldName = typeof labelField === 'string' ? labelField : undefined;
    const centroidsData = createCentroidsGeoJson(data, labelFieldName, labelFormatNumbers);

    const existingLabelSource = map.getSource(labelSourceId) as GeoJSONSource | undefined;
    if (existingLabelSource) {
      existingLabelSource.setData(centroidsData);
    } else {
      map.addSource(labelSourceId, {
        type: 'geojson',
        data: centroidsData,
      });
    }

    if (!map.getLayer(layerIdLabel)) {
      const textField =
        typeof labelField === 'string'
          ? labelFormatNumbers
            ? ['get', `${labelField}_formatted`]
            : ['get', labelField]
          : labelField;

      map.addLayer({
        id: layerIdLabel,
        type: 'symbol',
        source: labelSourceId,
        minzoom: labelMinZoom ?? minZoom,
        maxzoom: labelMaxZoom ?? maxZoom,
        ...(labelFilter && { filter: labelFilter as maplibregl.FilterSpecification }),
        layout: {
          visibility: 'visible',
          'text-field': textField as maplibregl.ExpressionSpecification,
          'text-font': labelFont,
          'text-size': labelSize,
          'text-anchor': labelAnchor,
          'text-allow-overlap': labelAllowOverlap,
          'text-ignore-placement': labelAllowOverlap,
          ...(labelOffset && { 'text-offset': labelOffset }),
          'symbol-placement': 'point',
        },
        paint: {
          'text-color': labelColor,
          'text-halo-color': labelHaloColor,
          'text-halo-width': labelHaloWidth,
          ...(labelOpacity !== undefined && {
            'text-opacity': (Array.isArray(labelOpacity) ? labelOpacity : labelOpacity) as number,
          }),
        },
      });
    }
  }, [
    map,
    isLoaded,
    data,
    labelField,
    labelFormatNumbers,
    labelFilter,
    labelOpacity,
    labelFont,
    labelSize,
    labelColor,
    labelHaloColor,
    labelHaloWidth,
    labelAnchor,
    labelOffset,
    labelAllowOverlap,
    labelMinZoom,
    labelMaxZoom,
    minZoom,
    maxZoom,
    labelSourceId,
    layerIdLabel,
  ]);

  useEffect(() => {
    if (!map || !isLoaded || !labelField) return;
    if (!map.getLayer(layerIdLabel)) return;

    const textField =
      typeof labelField === 'string'
        ? labelFormatNumbers
          ? ['get', `${labelField}_formatted`]
          : ['get', labelField]
        : labelField;

    map.setLayoutProperty(layerIdLabel, 'text-field', textField);
    map.setLayoutProperty(layerIdLabel, 'text-size', labelSize);
    map.setLayoutProperty(layerIdLabel, 'text-anchor', labelAnchor);
    map.setLayoutProperty(layerIdLabel, 'text-allow-overlap', labelAllowOverlap);
    map.setLayoutProperty(layerIdLabel, 'text-ignore-placement', labelAllowOverlap);
    if (labelOffset) {
      map.setLayoutProperty(layerIdLabel, 'text-offset', labelOffset);
    }
    if (labelFilter) {
      map.setFilter(layerIdLabel, labelFilter as maplibregl.FilterSpecification);
    }
  }, [
    map,
    isLoaded,
    labelField,
    labelFormatNumbers,
    labelSize,
    labelAnchor,
    labelOffset,
    labelAllowOverlap,
    labelFilter,
    layerIdLabel,
  ]);

  useEffect(() => {
    if (!map || !isLoaded || !labelField) return;
    if (!map.getLayer(layerIdLabel)) return;

    map.setPaintProperty(layerIdLabel, 'text-color', labelColor);
    map.setPaintProperty(layerIdLabel, 'text-halo-color', labelHaloColor);
    map.setPaintProperty(layerIdLabel, 'text-halo-width', labelHaloWidth);
    if (labelOpacity !== undefined) {
      map.setPaintProperty(
        layerIdLabel,
        'text-opacity',
        Array.isArray(labelOpacity) ? labelOpacity : labelOpacity
      );
    }
  }, [map, isLoaded, labelField, labelColor, labelHaloColor, labelHaloWidth, labelOpacity, layerIdLabel]);

  useEffect(() => {
    if (!map || !isLoaded || !data) return;

    const labelSource = map.getSource(labelSourceId) as GeoJSONSource | undefined;
    if (labelSource && labelField) {
      const labelFieldName = typeof labelField === 'string' ? labelField : undefined;
      const centroidsData = createCentroidsGeoJson(data, labelFieldName, labelFormatNumbers);
      labelSource.setData(centroidsData);
    }
  }, [map, isLoaded, data, labelSourceId, labelField, labelFormatNumbers]);
}
