import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';

interface UseLayerPaintPropertiesArgs {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  hoverable: boolean;
  fillColor: unknown;
  fillOpacity: unknown;
  fillPattern?: unknown;
  hoverFillColor?: unknown;
  hoverFillOpacity?: number;
  lineColor: unknown;
  lineWidth: unknown;
  lineOpacity: unknown;
  hoverLineColor?: unknown;
  hoverLineWidth?: number;
  circleRadius: unknown;
  circleColor: unknown;
  circleOpacity: unknown;
  circleStrokeColor: unknown;
  circleStrokeWidth: unknown;
  layerIdFill: string;
  layerIdLine: string;
  layerIdCircle: string;
}

export function useLayerPaintProperties({
  map,
  isLoaded,
  hoverable,
  fillColor,
  fillOpacity,
  fillPattern,
  hoverFillColor,
  hoverFillOpacity,
  lineColor,
  lineWidth,
  lineOpacity,
  hoverLineColor,
  hoverLineWidth,
  circleRadius,
  circleColor,
  circleOpacity,
  circleStrokeColor,
  circleStrokeWidth,
  layerIdFill,
  layerIdLine,
  layerIdCircle,
}: UseLayerPaintPropertiesArgs) {
  useEffect(() => {
    if (!map || !isLoaded) return;

    if (map.getLayer(layerIdFill)) {
      if (hoverable && hoverFillColor) {
        map.setPaintProperty(layerIdFill, 'fill-color', [
          'case',
          ['boolean', ['feature-state', 'hover'], false],
          hoverFillColor,
          fillColor,
        ]);
      } else {
        map.setPaintProperty(layerIdFill, 'fill-color', fillColor);
      }

      const hoverOpacity = hoverFillOpacity ?? Math.min((fillOpacity as number) + 0.2, 1);
      map.setPaintProperty(
        layerIdFill,
        'fill-opacity',
        hoverable
          ? [
              'case',
              ['boolean', ['feature-state', 'hover'], false],
              hoverOpacity,
              fillOpacity as number,
            ]
          : fillOpacity
      );

      if (fillPattern !== undefined) {
        map.setPaintProperty(
          layerIdFill,
          'fill-pattern',
          fillPattern as maplibregl.ExpressionSpecification
        );
      }
    }

    if (map.getLayer(layerIdLine)) {
      if (hoverable && hoverLineColor) {
        map.setPaintProperty(layerIdLine, 'line-color', [
          'case',
          ['boolean', ['feature-state', 'hover'], false],
          hoverLineColor,
          lineColor,
        ]);
      } else {
        map.setPaintProperty(layerIdLine, 'line-color', lineColor);
      }

      const hoverWidth = hoverLineWidth ?? (lineWidth as number) + 1;
      map.setPaintProperty(
        layerIdLine,
        'line-width',
        hoverable
          ? [
              'case',
              ['boolean', ['feature-state', 'hover'], false],
              hoverWidth,
              lineWidth as number,
            ]
          : lineWidth
      );

      map.setPaintProperty(layerIdLine, 'line-opacity', lineOpacity);
    }

    if (map.getLayer(layerIdCircle)) {
      map.setPaintProperty(layerIdCircle, 'circle-radius', circleRadius);
      map.setPaintProperty(layerIdCircle, 'circle-color', circleColor);
      map.setPaintProperty(layerIdCircle, 'circle-opacity', circleOpacity);
      map.setPaintProperty(layerIdCircle, 'circle-stroke-color', circleStrokeColor);
      map.setPaintProperty(layerIdCircle, 'circle-stroke-width', circleStrokeWidth);
    }
  }, [
    map,
    isLoaded,
    hoverable,
    fillColor,
    fillOpacity,
    fillPattern,
    hoverFillColor,
    hoverFillOpacity,
    lineColor,
    lineWidth,
    lineOpacity,
    hoverLineColor,
    hoverLineWidth,
    circleRadius,
    circleColor,
    circleOpacity,
    circleStrokeColor,
    circleStrokeWidth,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
  ]);
}
