/**
 * Hook for programmatic map control
 */

import { useCallback, useMemo } from 'react';
import type { LngLatBoundsLike, FitBoundsOptions, FlyToOptions, EaseToOptions } from 'maplibre-gl';

import { useGeoMap } from '../components/GeoMap/context';
import type { GeoCoordinates, GeoBounds, MapViewport, MapControls } from '../types';

/**
 * Hook that provides methods for programmatic map manipulation.
 * Must be used within a GeoMap component.
 * 
 * @example
 * ```tsx
 * function MyComponent() {
 *   const controls = useMapControls();
 *   
 *   const handleFitToData = () => {
 *     controls.fitBounds([-10, 35, 40, 70], { padding: 50 });
 *   };
 *   
 *   return <button onClick={handleFitToData}>Fit to Europe</button>;
 * }
 * ```
 */
export function useMapControls(): MapControls {
  const { map, isLoaded } = useGeoMap();

  const fitBounds = useCallback((
    bounds: GeoBounds | LngLatBoundsLike, 
    options?: FitBoundsOptions
  ) => {
    if (!map || !isLoaded) return;
    map.fitBounds(bounds as LngLatBoundsLike, options);
  }, [map, isLoaded]);

  const flyTo = useCallback((options: FlyToOptions) => {
    if (!map || !isLoaded) return;
    map.flyTo(options);
  }, [map, isLoaded]);

  const easeTo = useCallback((options: EaseToOptions) => {
    if (!map || !isLoaded) return;
    map.easeTo(options);
  }, [map, isLoaded]);

  const jumpTo = useCallback((options: { 
    center?: GeoCoordinates; 
    zoom?: number; 
    bearing?: number; 
    pitch?: number;
  }) => {
    if (!map || !isLoaded) return;
    map.jumpTo(options);
  }, [map, isLoaded]);

  const setZoom = useCallback((zoom: number) => {
    if (!map || !isLoaded) return;
    map.setZoom(zoom);
  }, [map, isLoaded]);

  const setCenter = useCallback((center: GeoCoordinates) => {
    if (!map || !isLoaded) return;
    map.setCenter(center);
  }, [map, isLoaded]);

  const getViewport = useCallback((): MapViewport | null => {
    if (!map || !isLoaded) return null;
    
    const center = map.getCenter();
    return {
      center: [center.lng, center.lat],
      zoom: map.getZoom(),
      bearing: map.getBearing(),
      pitch: map.getPitch(),
    };
  }, [map, isLoaded]);

  const getBounds = useCallback((): GeoBounds | null => {
    if (!map || !isLoaded) return null;
    
    const bounds = map.getBounds();
    return [
      bounds.getWest(),
      bounds.getSouth(),
      bounds.getEast(),
      bounds.getNorth(),
    ];
  }, [map, isLoaded]);

  return useMemo(() => ({
    fitBounds,
    flyTo,
    easeTo,
    jumpTo,
    setZoom,
    setCenter,
    getViewport,
    getBounds,
  }), [fitBounds, flyTo, easeTo, jumpTo, setZoom, setCenter, getViewport, getBounds]);
}

