/**
 * GeoMap context for sharing map instance with child components
 */

import { createContext, useContext } from 'react';
import type { GeoMapContextValue } from '../../types';

export const GeoMapContext = createContext<GeoMapContextValue>({
  map: null,
  isLoaded: false,
});

/**
 * Hook to access map instance from child components
 */
export function useGeoMap(): GeoMapContextValue {
  const context = useContext(GeoMapContext);
  
  if (context === undefined) {
    throw new Error('useGeoMap must be used within a GeoMap component');
  }
  
  return context;
}

