/**
 * GeoJsonLayer — Renders GeoJSON data on the map
 * 
 * Supports fill (polygons), line (strokes), circle (points), and text labels
 * with optional hover and click interactions.
 * 
 * @example Basic fill layer
 * ```tsx
 * <GeoJsonLayer
 *   id="countries"
 *   data={countriesGeoJson}
 *   type="fill"
 *   fillColor="#3b82f6"
 *   fillOpacity={0.5}
 *   hoverable
 *   onFeatureClick={(e) => console.log(e.feature.properties.name)}
 * />
 * ```
 * 
 * @example With labels
 * ```tsx
 * <GeoJsonLayer
 *   id="regions"
 *   data={regionsGeoJson}
 *   fillColor="#3b82f6"
 *   labelField="name"
 *   labelSize={12}
 *   labelColor="#333"
 * />
 * ```
 */

import { useEffect, useRef } from 'react';
import type { MapGeoJSONFeature } from 'maplibre-gl';

import { useGeoMap } from './context';
import { useFeatureHover } from './useFeatureHover';
import { useFeatureClick } from './useFeatureClick';
import { useLabelLayer } from './useLabelLayer';
import { useLayerPaintProperties } from './useLayerPaintProperties';
import { useGeoJsonSource } from './useGeoJsonSource';
import { useGeoJsonLayers } from './useGeoJsonLayers';
import { useLayerVisibility } from './useLayerVisibility';
import type { GeoJsonLayerProps, FeatureEvent, GeoCoordinates } from '../../types';

/** Default style values */
const DEFAULTS = {
  fillColor: '#3b82f6',
  fillOpacity: 0.5,
  lineColor: '#1d4ed8',
  lineWidth: 1,
  lineOpacity: 1,
  circleRadius: 6,
  circleColor: '#3b82f6',
  circleOpacity: 1,
  circleStrokeColor: '#ffffff',
  circleStrokeWidth: 1,
  // Label defaults
  labelSize: 12,
  labelColor: '#333333',
  labelHaloColor: '#ffffff',
  labelHaloWidth: 1.5,
  labelFont: ['Noto Sans Bold', 'Noto Sans Regular'] as string[],
  labelAnchor: 'center' as const,
};

/**
 * Creates a FeatureEvent from MapLibre event data.
 */
function createFeatureEvent<P>(
  feature: MapGeoJSONFeature,
  coordinates: GeoCoordinates,
  originalEvent: MouseEvent
): FeatureEvent<P> {
  return {
    feature: {
      type: 'Feature',
      geometry: feature.geometry,
      properties: feature.properties as P,
      id: feature.id,
    },
    originalFeature: feature,
    coordinates,
    originalEvent,
  };
}

/**
 * Component that renders GeoJSON data as a layer on the map.
 */
export function GeoJsonLayer<P = GeoJSON.GeoJsonProperties>({
  id,
  data,
  type = 'fill',
  visible = true,
  // zIndex, // TODO: implement layer ordering
  minZoom,
  maxZoom,
  filter,
  // Fill styles
  fillColor = DEFAULTS.fillColor,
  fillOpacity = DEFAULTS.fillOpacity,
  fillPattern,
  // Line styles
  lineColor = DEFAULTS.lineColor,
  lineWidth = DEFAULTS.lineWidth,
  lineOpacity = DEFAULTS.lineOpacity,
  lineDashArray,
  lineCap,
  lineJoin,
  // Circle styles
  circleRadius = DEFAULTS.circleRadius,
  circleColor = DEFAULTS.circleColor,
  circleOpacity = DEFAULTS.circleOpacity,
  circleStrokeColor = DEFAULTS.circleStrokeColor,
  circleStrokeWidth = DEFAULTS.circleStrokeWidth,
  // Label styles
  labelField,
  labelSize = DEFAULTS.labelSize,
  labelColor = DEFAULTS.labelColor,
  labelHaloColor = DEFAULTS.labelHaloColor,
  labelHaloWidth = DEFAULTS.labelHaloWidth,
  labelFont = DEFAULTS.labelFont,
  labelAnchor = DEFAULTS.labelAnchor,
  labelOffset,
  labelMinZoom,
  labelMaxZoom,
  labelAllowOverlap = false,
  labelFormatNumbers = false,
  labelFilter,
  labelOpacity,
  // Hover styles
  hoverFillColor,
  hoverFillOpacity,
  hoverLineColor,
  hoverLineWidth,
  // Interactions
  hoverable = false,
  onFeatureClick,
  onFeatureHover,
}: GeoJsonLayerProps<P>): null {
  const { map, isLoaded } = useGeoMap();
  
  // Layer IDs
  const sourceId = `${id}-source`;
  const labelSourceId = `${id}-label-source`; // Separate source for centroids
  const layerIdFill = `${id}-fill`;
  const layerIdLine = `${id}-line`;
  const layerIdCircle = `${id}-circle`;
  const layerIdLabel = `${id}-label`;
  
  // Track hovered feature for state management
  const hoveredFeatureId = useRef<string | number | null>(null);

  useGeoJsonSource({
    map,
    isLoaded,
    data,
    sourceId,
  });

  useGeoJsonLayers({
    map,
    isLoaded,
    data,
    id,
    type,
    visible,
    minZoom,
    maxZoom,
    filter,
    sourceId,
    labelSourceId,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
    layerIdLabel,
    fillColor,
    fillOpacity,
    fillPattern,
    lineColor,
    lineWidth,
    lineOpacity,
    lineDashArray,
    lineCap,
    lineJoin,
    circleRadius,
    circleColor,
    circleOpacity,
    circleStrokeColor,
    circleStrokeWidth,
  } as any);

  useLayerVisibility({
    map,
    isLoaded,
    visible,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
    layerIdLabel,
  });

  useLayerPaintProperties({
    map,
    isLoaded,
    hoverable,
    fillColor,
    fillOpacity,
    fillPattern,
    hoverFillColor,
    hoverFillOpacity,
    lineColor,
    lineWidth,
    lineOpacity,
    hoverLineColor,
    hoverLineWidth,
    circleRadius,
    circleColor,
    circleOpacity,
    circleStrokeColor,
    circleStrokeWidth,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
  } as any);

  useLabelLayer({
    map,
    isLoaded,
    data: typeof data === 'string' ? null : data ?? null,
    labelField,
    labelFormatNumbers,
    labelFilter,
    labelOpacity,
    labelSize: labelSize as number,
    labelColor: labelColor as string,
    labelHaloColor,
    labelHaloWidth,
    labelFont,
    labelAnchor,
    labelOffset,
    labelMinZoom,
    labelMaxZoom,
    labelAllowOverlap,
    minZoom,
    maxZoom,
    labelSourceId,
    layerIdLabel,
  });

  useFeatureHover<P>({
    map,
    isLoaded,
    hoverable,
    type,
    sourceId,
    layerIdFill,
    layerIdCircle,
    hoveredFeatureId,
    onFeatureHover,
    createFeatureEvent,
  });

  useFeatureClick<P>({
    map,
    isLoaded,
    type,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
    onFeatureClick,
    createFeatureEvent,
  });

  return null;
}
