/**
 * Popup — A floating card component anchored to map coordinates.
 * 
 * Displays custom content at a specific location on the map.
 * Automatically repositions when the map moves.
 * 
 * @example Basic usage
 * ```tsx
 * <GeoMap>
 *   <Popup 
 *     coordinates={[37.6173, 55.7558]} 
 *     onClose={() => setIsOpen(false)}
 *   >
 *     <h3>Moscow</h3>
 *     <p>Capital of Russia</p>
 *   </Popup>
 * </GeoMap>
 * ```
 * 
 * @example With feature data
 * ```tsx
 * {selectedFeature && (
 *   <Popup 
 *     coordinates={clickCoordinates}
 *     onClose={() => setSelectedFeature(null)}
 *   >
 *     <FeatureCard feature={selectedFeature} />
 *   </Popup>
 * )}
 * ```
 */

import { useEffect, useRef, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import maplibregl from 'maplibre-gl';

import { useGeoMap } from './context';
import type { PopupProps } from '../../types';
import styles from './Popup.module.css';

export function Popup({
  coordinates,
  children,
  onClose,
  className,
  anchor = 'bottom',
  offset = [0, -10],
  closeButton = true,
  closeOnClick = false,
  closeOnMapClick = true,
  maxWidth = '320px',
}: PopupProps): ReactNode {
  const { map, isLoaded } = useGeoMap();
  const popupRef = useRef<maplibregl.Popup | null>(null);
  const [container, setContainer] = useState<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!map || !isLoaded || !coordinates) return;

    // Create popup container
    const popupContainer = document.createElement('div');
    popupContainer.className = styles.popupContent;
    if (className) {
      popupContainer.classList.add(className);
    }

    // Create MapLibre popup
    const popup = new maplibregl.Popup({
      closeButton: false, // We'll render our own close button
      closeOnClick: closeOnClick,
      closeOnMove: false,
      anchor,
      offset,
      maxWidth,
      className: styles.popup,
    });

    popup.setLngLat(coordinates);
    popup.setDOMContent(popupContainer);
    popup.addTo(map);

    popupRef.current = popup;
    setContainer(popupContainer);

    // Handle close on map click
    const handleMapClick = () => {
      if (closeOnMapClick && onClose) {
        onClose();
      }
    };

    if (closeOnMapClick) {
      // Delay to avoid triggering on the same click that opened the popup
      setTimeout(() => {
        map.on('click', handleMapClick);
      }, 100);
    }

    // Handle popup close event
    popup.on('close', () => {
      onClose?.();
    });

    return () => {
      map.off('click', handleMapClick);
      popup.remove();
      popupRef.current = null;
      setContainer(null);
    };
  }, [map, isLoaded, coordinates, anchor, offset, maxWidth, closeOnClick, closeOnMapClick, onClose, className]);

  // Update position when coordinates change
  useEffect(() => {
    if (popupRef.current && coordinates) {
      popupRef.current.setLngLat(coordinates);
    }
  }, [coordinates]);

  // Render content into popup container using portal
  if (!container) return null;

  return createPortal(
    <>
      {closeButton && (
        <button 
          className={styles.closeButton}
          onClick={onClose}
          aria-label="Закрыть"
          type="button"
        >
          ×
        </button>
      )}
      <div className={styles.content}>
        {children}
      </div>
    </>,
    container
  );
}

