import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';
import type { MapLayerMouseEvent, MapGeoJSONFeature } from 'maplibre-gl';

import type { FeatureEvent, GeoCoordinates, GeoJsonLayerProps } from '../../types';

type CreateFeatureEvent<P> = (
  feature: MapGeoJSONFeature,
  coordinates: GeoCoordinates,
  originalEvent: MouseEvent
) => FeatureEvent<P>;

interface UseFeatureClickArgs<P> {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  type: GeoJsonLayerProps['type'];
  layerIdFill: string;
  layerIdLine: string;
  layerIdCircle: string;
  onFeatureClick?: (event: FeatureEvent<P>) => void;
  createFeatureEvent: CreateFeatureEvent<P>;
}

export function useFeatureClick<P>({
  map,
  isLoaded,
  type,
  layerIdFill,
  layerIdLine,
  layerIdCircle,
  onFeatureClick,
  createFeatureEvent,
}: UseFeatureClickArgs<P>) {
  useEffect(() => {
    if (!map || !isLoaded || !onFeatureClick) return;

    if (type === 'fill') {
      if (!map.getLayer(layerIdFill)) return;

      const handleMapClick = (e: MapLayerMouseEvent) => {
        const features = map.queryRenderedFeatures(e.point, { layers: [layerIdFill] });
        if (!features || features.length === 0) return;
        const feature = features[0] as MapGeoJSONFeature;
        const coords: GeoCoordinates = [e.lngLat.lng, e.lngLat.lat];
        onFeatureClick(createFeatureEvent(feature, coords, e.originalEvent));
      };

      map.on('click', handleMapClick);

      return () => {
        map.off('click', handleMapClick);
      };
    }

    const targetLayer = type === 'line' ? layerIdLine : layerIdCircle;
    if (!map.getLayer(targetLayer)) return;

    const handleClick = (e: MapLayerMouseEvent) => {
      if (!e.features || e.features.length === 0) return;
      const feature = e.features[0];
      const coords: GeoCoordinates = [e.lngLat.lng, e.lngLat.lat];
      onFeatureClick(createFeatureEvent(feature, coords, e.originalEvent));
    };

    map.on('click', targetLayer, handleClick);

    return () => {
      map.off('click', targetLayer, handleClick);
    };
  }, [
    map,
    isLoaded,
    onFeatureClick,
    type,
    layerIdFill,
    layerIdLine,
    layerIdCircle,
    createFeatureEvent,
  ]);
}
