import { useEffect } from 'react';
import type maplibregl from 'maplibre-gl';
import type { GeoJSONSource } from 'maplibre-gl';

interface UseGeoJsonSourceArgs {
  map: maplibregl.Map | null;
  isLoaded: boolean;
  data?: GeoJSON.GeoJSON | string | null;
  sourceId: string;
}

export function useGeoJsonSource({
  map,
  isLoaded,
  data,
  sourceId,
}: UseGeoJsonSourceArgs) {
  useEffect(() => {
    if (!map || !isLoaded || !data) return;

    const existingSource = map.getSource(sourceId) as GeoJSONSource | undefined;
    if (existingSource) {
      existingSource.setData(data as GeoJSON.GeoJSON);
      return;
    }

    map.addSource(sourceId, {
      type: 'geojson',
      data: data as GeoJSON.GeoJSON,
      generateId: true,
    });
  }, [map, isLoaded, data, sourceId]);
}
