import type { GeoJSON } from 'geojson';
import polylabel from 'polylabel';

/**
 * Approximate bounding box area of a ring (for comparison only).
 */
function ringBBoxArea(ring: GeoJSON.Position[]): number {
  if (ring.length === 0) return 0;

  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;

  for (const coord of ring) {
    if (coord[0] < minX) minX = coord[0];
    if (coord[0] > maxX) maxX = coord[0];
    if (coord[1] < minY) minY = coord[1];
    if (coord[1] > maxY) maxY = coord[1];
  }

  return (maxX - minX) * (maxY - minY);
}

/**
 * Compute optimal label point using polylabel algorithm (pole of inaccessibility).
 * For MultiPolygon, uses the largest polygon.
 */
function computeLabelPoint(geometry: GeoJSON.Geometry): [number, number] | null {
  if (geometry.type === 'Point') {
    return geometry.coordinates as [number, number];
  }

  if (geometry.type === 'MultiPoint' && geometry.coordinates.length > 0) {
    return geometry.coordinates[0] as [number, number];
  }

  if (geometry.type === 'LineString' && geometry.coordinates.length > 0) {
    const mid = Math.floor(geometry.coordinates.length / 2);
    return geometry.coordinates[mid] as [number, number];
  }

  if (geometry.type === 'MultiLineString' && geometry.coordinates.length > 0) {
    const line = geometry.coordinates[0];
    const mid = Math.floor(line.length / 2);
    return line[mid] as [number, number];
  }

  if (geometry.type === 'Polygon' && geometry.coordinates.length > 0) {
    // polylabel expects array of rings: [[outer], [hole1], [hole2], ...]
    const result = polylabel(geometry.coordinates as number[][][], 1.0);
    return [result[0], result[1]];
  }

  if (geometry.type === 'MultiPolygon' && geometry.coordinates.length > 0) {
    // Find the largest polygon by bounding box area
    let largestPolygon: GeoJSON.Position[][] | null = null;
    let largestArea = 0;

    for (const polygon of geometry.coordinates) {
      if (polygon.length > 0) {
        const ring = polygon[0];
        const area = ringBBoxArea(ring);
        if (area > largestArea) {
          largestArea = area;
          largestPolygon = polygon;
        }
      }
    }

    if (largestPolygon) {
      const result = polylabel(largestPolygon as number[][][], 1.0);
      return [result[0], result[1]];
    }
    return null;
  }

  return null;
}

/**
 * Format a number with K, M, B suffixes.
 * Also handles numeric strings (e.g., from CSV import).
 */
function formatNumber(value: unknown): string {
  let numValue: number;
  if (typeof value === 'number') {
    numValue = value;
  } else if (typeof value === 'string') {
    const cleaned = value.replace(/,/g, '').trim();
    numValue = parseFloat(cleaned);
    if (isNaN(numValue)) {
      return value;
    }
  } else {
    return String(value ?? '');
  }

  if (isNaN(numValue)) {
    return String(value ?? '');
  }

  const absValue = Math.abs(numValue);
  const sign = numValue < 0 ? '-' : '';

  if (absValue >= 1_000_000_000) {
    const formatted = absValue / 1_000_000_000;
    return (
      sign +
      (formatted >= 100 ? Math.round(formatted) : formatted.toFixed(1).replace(/\.0$/, '')) +
      'B'
    );
  }
  if (absValue >= 1_000_000) {
    const formatted = absValue / 1_000_000;
    return (
      sign +
      (formatted >= 100 ? Math.round(formatted) : formatted.toFixed(1).replace(/\.0$/, '')) +
      'M'
    );
  }
  if (absValue >= 1_000) {
    const formatted = absValue / 1_000;
    return (
      sign +
      (formatted >= 100 ? Math.round(formatted) : formatted.toFixed(1).replace(/\.0$/, '')) +
      'K'
    );
  }

  return String(numValue);
}

/**
 * Convert GeoJSON to point centroids for labeling.
 * Optionally formats numeric label values with K/M/B suffixes.
 */
export function createCentroidsGeoJson(
  data: GeoJSON.GeoJSON,
  labelField?: string,
  formatNumbers?: boolean
): GeoJSON.FeatureCollection<GeoJSON.Point> {
  const features: GeoJSON.Feature<GeoJSON.Point>[] = [];
  const formattedField = labelField ? `${labelField}_formatted` : undefined;

  const processFeature = (feature: GeoJSON.Feature) => {
    const centroid = computeLabelPoint(feature.geometry);
    if (centroid) {
      let properties = { ...feature.properties };

      if (formatNumbers && labelField && formattedField && properties) {
        const value = properties[labelField];
        properties = {
          ...properties,
          [formattedField]: formatNumber(value),
        };
      }

      features.push({
        type: 'Feature',
        properties,
        id: feature.id,
        geometry: {
          type: 'Point',
          coordinates: centroid,
        },
      });
    }
  };

  if (data.type === 'FeatureCollection') {
    for (const feature of data.features) {
      processFeature(feature);
    }
  } else if (data.type === 'Feature') {
    processFeature(data);
  }

  return {
    type: 'FeatureCollection',
    features,
  };
}
