/**
 * GeoMap — Main map component
 * 
 * A React wrapper around MapLibre GL JS that provides:
 * - Declarative API for map configuration
 * - Context for child layer components
 * - Viewport change tracking
 * 
 * @example
 * ```tsx
 * <GeoMap
 *   style="positron"
 *   viewport={{ center: [37.6173, 55.7558], zoom: 10 }}
 *   onViewportChange={(vp) => console.log(vp)}
 * >
 *   <GeoJsonLayer id="regions" data={geoJsonData} />
 * </GeoMap>
 * ```
 */

import { useRef, useEffect, useState, useMemo, type ReactNode } from 'react';
import maplibregl, { NavigationControl, FullscreenControl, type Map, type StyleSpecification } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';

import { GeoMapContext } from './context';
import { resolveMapStyle, DEFAULT_STYLE_PRESET } from '../../constants';
import type { GeoMapProps, MapViewport } from '../../types';
import styles from './GeoMap.module.css';

/** Default viewport — centered on Moscow */
const DEFAULT_VIEWPORT: MapViewport = {
  center: [37.6173, 55.7558],
  zoom: 4,
  bearing: 0,
  pitch: 0,
};

/**
 * Main map component that wraps MapLibre GL JS.
 * 
 * Provides React context to child components (layers, markers) for accessing
 * the underlying map instance.
 */
export function GeoMap({
  viewport,
  style = DEFAULT_STYLE_PRESET,
  className,
  containerStyle,
  onLoad,
  onViewportChange,
  controls = true,
  scrollZoom = true,
  dragPan = true,
  children,
}: GeoMapProps): ReactNode {
  const containerRef = useRef<HTMLDivElement>(null);
  const [mapInstance, setMapInstance] = useState<Map | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  // Store initial viewport in ref to avoid re-initialization
  const initialViewportRef = useRef<MapViewport>({
    ...DEFAULT_VIEWPORT,
    ...viewport,
  });

  // Track current style to avoid unnecessary setStyle calls
  const currentStyleRef = useRef<string | StyleSpecification | null>(null);

  // Resolve style preset to URL
  const resolvedStyle = resolveMapStyle(style);

  // Initialize map
  useEffect(() => {
    if (!containerRef.current || mapInstance) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: resolvedStyle,
      center: initialViewportRef.current.center,
      zoom: initialViewportRef.current.zoom,
      bearing: initialViewportRef.current.bearing,
      pitch: initialViewportRef.current.pitch,
      scrollZoom,
      dragPan,
      attributionControl: {},
    });

    // Add navigation controls if enabled
    if (controls) {
      map.addControl(new NavigationControl({ showCompass: true }), 'top-right');
      map.addControl(new FullscreenControl(), 'top-right');
    }

    map.on('load', () => {
      currentStyleRef.current = resolvedStyle;
      setIsLoaded(true);
      onLoad?.(map);
    });

    // Track viewport changes
    const handleMoveEnd = () => {
      if (!onViewportChange) return;
      
      const center = map.getCenter();
      onViewportChange({
        center: [center.lng, center.lat],
        zoom: map.getZoom(),
        bearing: map.getBearing(),
        pitch: map.getPitch(),
      });
    };

    map.on('moveend', handleMoveEnd);

    setMapInstance(map);

    return () => {
      map.off('moveend', handleMoveEnd);
      map.remove();
      setMapInstance(null);
      setIsLoaded(false);
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Update style if changed (after initial load)
  useEffect(() => {
    if (mapInstance && isLoaded) {
      const newStyle = resolveMapStyle(style);
      // Only call setStyle if style actually changed
      if (currentStyleRef.current !== newStyle) {
        console.log(`[GeoMap] Style changed from ${currentStyleRef.current} to ${newStyle}`);
        currentStyleRef.current = newStyle;
        mapInstance.setStyle(newStyle);
      }
    }
  }, [style, isLoaded, mapInstance]);

  const containerClassName = [styles.container, className].filter(Boolean).join(' ');

  // Memoize context value to prevent unnecessary re-renders
  const contextValue = useMemo(() => ({ 
    map: mapInstance, 
    isLoaded 
  }), [mapInstance, isLoaded]);

  return (
    <GeoMapContext.Provider value={contextValue}>
      <div 
        ref={containerRef} 
        className={containerClassName}
        style={containerStyle}
        data-testid="geomap-container"
      />
      {isLoaded && children}
    </GeoMapContext.Provider>
  );
}
